whole=sorted(n for n,v in inv['files'].items() if n.startswith('crates/cambium/cambium-genet-winit-host/') and n not in guards and cov.get(n,{}).get('sha256')==v['sha256'] and cov[n]['through']==v['chars'])
assert len(whole)==14 and sum(inv['files'][n]['chars'] for n in whole)==170606
