def function(source,name):
 start=source.index('fn '+name);return source[start:source.index('\n}',start)+2]
dec=(ROOT/'crates/cambium/cambium-genet-winit-host/src/decorations.rs').read_text();t4=(ROOT/'crates/cambium/cambium-genet-winit-host/examples/t4_receipt.rs').read_text();fixture=(HERE/'native_authority_v2_probe.rs').read_text()
functions=[function(dec,'window_control_node'),*(function(t4,n) for n in ['css_rgb','leaf_style','plain_style','pair_view'])];assert all(f in fixture for f in functions)
notes,authority=load('review_notes.json'),load('authority_map.json');assert notes['findings'][-1]['id']=='Q310' and authority['entries'][-1]['id']=='A804'
findings=[
 {'id':'Q311','title':'T4 receipt program exits successfully without enforcing its comparison or completeness conditions','source':'crates/cambium/cambium-genet-winit-host/examples/t4_receipt.rs:624,637,650','status':'source-verified success-path defect; full GPU fixture not executed','evidence':'The capture path records matched and non_vacuous booleans, but after run returns main only formats those fields into results_raw.md, writes it and prints wrote receipt. It never rejects false matches, false non-vacuity, missing pairs/timing samples, absent lower counters or a changed Path-B counter. In particular control_lower_before == control_lower_after reports true for None == None. Closing before collecting all fixtures or collecting failed comparisons can therefore end normally and return process status 0, provided the event loop and file I/O themselves succeed. Raw report booleans may disclose failure to a human, but a successful process is not an acceptance gate for this receipt. No observed pixel pass/failure or actual fixture exit was run.','repair_triage':{'disposition':'documented under active read-only audit goal','reason':'Add an explicit complete-case acceptance predicate and fail the process on missing/failed conditions. Require both counter readings to exist; record timing sample completeness separately from correctness.'}},
 {'id':'Q312','title':'T4 unlayered reference is placed into the wrong column by its own later CSS','source':'crates/cambium/cambium-genet-winit-host/examples/t4_receipt.rs:220,248,253,546','status':'verified original extracted pair/style functions with actual current runner/retained layout over exact retained suppliers','evidence':'pair_view constructs the bare control style with left:616px;top:16px and then appends plain_style(dx,dy,...), which declares left/top again. At the first fixture offset 4,4 the unchanged extracted original functions, real current Cambium Runner and Rootstock OwnedLayout report the bare control rect (4,4,64,48). It is consequently outside the intended third reference column and can cover the retained-path column instead. Comparing the third crop against the layered reference is not the claimed non-vacuity control. The full native/GPU T4 run was not executed; equal-width frame cropping versus fixed 300px panel spacing is a further source follow-up.','diagnostics':['native_authority_v2_probe_receipt.json','native_authority_v2_test_count_receipt.json'],'repair_triage':{'disposition':'documented under active read-only audit goal','reason':'Place the unlayered content inside a separate positioned column, or compose the intended absolute coordinates once. Derive captures from actual panel bounds and require independent non-vacuity and matching gates.'}},
 {'id':'Q313','title':'Native caption control lookup substitutes raw aria-label for the shared accessible-name authority','source':'crates/cambium/cambium-genet-winit-host/src/decorations.rs:106,113,121; crates/cambium/cambium-genet-winit-host/src/lib.rs:523','status':'verified exact extracted lookup against actual current neutral accessibility projection over retained exact suppliers; no OS hit-test run','evidence':'window_control_node says it reuses button semantics and the accessible label rather than adding a second native-only marker, but it recursively matches only button/role plus raw aria-label. Three real ScriptedDom/OwnedLayout/projection checks show text-only Maximize and aria-labelledby Maximize have the proper shared projected name but are not found by native lookup; a raw Maximize aria-label overridden by aria-labelledby Agrandir is still selected as Maximize by the native lookup, while the projection correctly announces Agrandir. WinitHost::refresh_snap_layout_rect calls this helper for the Win32 maximize region, making native target identity diverge from shared semantic identity. This proves lookup/projection disagreement, not observed Win32 Snap UI behavior.','diagnostics':['native_authority_v2_probe_receipt.json','native_authority_v2_test_count_receipt.json'],'repair_triage':{'disposition':'documented under active read-only audit goal','reason':'Resolve control role/name through the shared accessible semantics and visibility authority, then map that same node to painted bounds. Do not grow another native-only naming algorithm.'}}
]
for f in findings:f['verification']=NAME
notes['findings'].extend(findings)
rows=[
 ('Receipt generation and receipt acceptance are different authorities','T4 collects and formats evidence but does not enforce acceptance.', ['examples/t4_receipt.rs'], 'Q311 records normal process completion despite false/incomplete report data, including missing counter equality. Q312 proves the claimed independent bare reference is laid out in the wrong column. Its private PNG writer is another local implementation; do not infer a PNG encoding bug merely from duplication.'),
 ('Native caption semantic identity forks the shared projection','Raw aria-label is a second native lookup policy despite the shared-semantics claim.', ['src/decorations.rs','src/lib.rs','src/caption_controls.rs'], 'Q313 demonstrates actual projection/lookup disagreement for content names and aria-labelledby precedence. CaptionLabels and HostOptions must manually share the same maximize string. The bridge follows retained painted geometry after lookup, but that does not make its semantic lookup shared.'),
 ('Headless harness shares core routing with adapter-specific omissions','Harness wraps actual WinitHost/Host but synthesizes coordinates, window facts and presentation.', ['src/harness.rs'], 'It uses current retained layout for selector click coordinates rather than a second taproot layout and marks synthetic presentation as non-GPU evidence. press_at/release_at directly set cursor, while move_to invokes pointer_moved; right-click prose still says no release even though current native source routes right release. Trace these route differences before equating harness gestures with complete native delivery.'),
 ('Window geometry and caption policy remain local to the native wrapper','The host owns native calls, restore snapshots, resize borders and custom drag policy.', ['src/decorations.rs','src/lib.rs'], 'Commands reuse the shared queue; native operations often discard platform errors and performed records requested/performed intent even without a real window. ClickCadence fixes time/slop constants rather than reading per-user system settings. Restore remembers floating geometry under maximize, but mixed-DPI monitor origins and unsupported position queries still need real platform evidence.'),
 ('First frame and open success do not prove successful presentation','Native open and resume complete after attempted redraw and a11y synchronization.', ['src/lib.rs'], 'open returns Ok(window) after first_frame, whose redraw returns void; resume_surface returns true for an existing window even when recovery is pending or surface recreation failed. These are lifecycle/existing-window facts, not a PresentedFrame receipt. Initial window creation and ApplicationHandler boot still use expect, and run returns only EventLoopError.'),
 ('Native/shared-device lifecycle delegates rendering authority','WinitSurface delegates to RenderCore/WindowSurface while recovery and host hooks retain CPU state.', ['src/lib.rs'], 'Shared-core embedding boots no new device, loss detachment runs on wakes including hidden hosts, suspend drops surface/producers and resume reuses the owner. Caption frame geometry and native Snap refresh stay outside Rootstock. No OS window/suspend/GPU recovery run was performed in this source pass.'),
 ('Native file acquisition erases several failure classes','Dialog cancellation, absent graphical backend and per-file read failure all become empty or omitted files.', ['src/files.rs'], 'The API documents None/empty behavior and chooses only a save path, leaving replacement/writing to callers. It synchronously reads unbounded chosen bytes and discards failed paths. Record this conversion/ownership boundary without inventing an error channel promised by the current FileEvent API.'),
 ('Native smoke scenarios distinguish logical routing from platform checks','Mesquite drives semantic actions and in-process captures; external probes own platform geometry claims.', ['examples/smoke.rs','examples/smoke.scn','examples/smoke_windows_snap.scn','examples/smoke_windows_maximized.scn','examples/smoke_wayland_app_frame.scn','examples/smoke_wayland_host_frame.scn','examples/smoke_x11_shadow.scn'], 'Product receipt_checks enforce changed digest/extent and optional alpha conditions, unlike T4 raw formatting. Scenario log lines alone do not establish the claimed external Snap/work-area/Wayland/X11 results. These scripts and fixtures were read, not executed in this pass.')
]
entries=[{'id':f'A{805+i}','domain':d,'claim':c,'implementations':['crates/cambium/cambium-genet-winit-host/'+p for p in paths],'assessment':a,'state':'current source read with qualified native-function/retained-layout probes','verification':NAME} for i,(d,c,paths,a) in enumerate(rows)];authority['entries'].extend(entries)
notes['review_followups'].extend([
 {'verification':NAME,'area':'T4 panel/capture geometry','detail':'The view spaces columns by 300px but crops frame.width/3; initial requested width is 960. Verify exact actual frame/panel bounds, rather than assuming a third of any window is one column. Do not treat the misplaced bare control or process exit as a valid accepted GPU receipt.'},
 {'verification':NAME,'area':'Harness versus native gesture completeness','detail':'Compare direct cursor assignment in press/release with native CursorMoved/pointer_moved hover transitions, and current right release/capture versus stale one-shot harness prose. Native focus loss cancels pointer but does not visibly clear held Tab/modifier state; trace before promoting stuck state.'}
])
